-- Irbid Drive (Roblox) - builds the map when the server starts, from ServerStorage.IrbidData (generated by tools/make_roblox.js from
-- OpenStreetMap roads + buildings and NASA SRTM terrain; the same data as the web game). Units in the data: decimetres, centred on the start.
local ServerStorage = game:GetService("ServerStorage")
local Workspace = game:GetService("Workspace")
local Lighting = game:GetService("Lighting")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Config = require(ReplicatedStorage:WaitForChild("Config"))

local DATA = ServerStorage:WaitForChild("IrbidData")
local Meta = require(DATA:WaitForChild("Meta"))
local S = Config.SCALE
local D = S / 10 -- decimetres -> studs

local function nums(s)
	local t = {}
	for n in string.gmatch(s, "-?%d+") do
		t[#t + 1] = tonumber(n)
	end
	return t
end

local function chunks(prefix)
	local list, i = {}, 1
	while DATA:FindFirstChild(prefix .. i) do
		list[#list + 1] = nums(require(DATA[prefix .. i]))
		i += 1
	end
	return list
end

Lighting.ClockTime = 14
Lighting.Brightness = 2.5
Lighting.OutdoorAmbient = Color3.fromRGB(150, 140, 125)
Workspace.Gravity = 196.2

local map = Instance.new("Folder")
map.Name = "IrbidMap"
map.Parent = Workspace
local roadsF = Instance.new("Folder"); roadsF.Name = "Roads"; roadsF.Parent = map
local bldF = Instance.new("Folder"); bldF.Name = "Buildings"; bldF.Parent = map

-- ---- terrain: 40 m tiles of ground, top 0.6 m under the road level ----
local T = Workspace.Terrain
local tile = 40 * S
for _, t in ipairs(chunks("Terrain")) do
	for i = 1, #t, 3 do
		local x, z, y = t[i] * D, t[i + 1] * D, t[i + 2] * D
		T:FillBlock(CFrame.new(x, y - 0.6 * S - 6, z), Vector3.new(tile, 12, tile), Enum.Material.Ground)
	end
	task.wait()
end

-- ---- roads: one part per OSM segment, sloped between the two terrain heights, overlapping at joints ----
local ROADC = {
	[0] = Color3.fromRGB(58, 60, 64),  -- major
	[1] = Color3.fromRGB(70, 72, 76),  -- local
	[2] = Color3.fromRGB(96, 92, 86),  -- service / alley
	[3] = Color3.fromRGB(58, 60, 64),  -- roundabout
}
local n = 0
for _, r in ipairs(chunks("Roads")) do
	for i = 1, #r, 8 do
		local a = Vector3.new(r[i] * D, r[i + 4] * D + 0.1 * S, r[i + 1] * D)
		local b = Vector3.new(r[i + 2] * D, r[i + 5] * D + 0.1 * S, r[i + 3] * D)
		local w = r[i + 6] * D
		local len = (b - a).Magnitude
		local p = Instance.new("Part")
		p.Anchored = true
		p.CanTouch = false
		p.TopSurface = Enum.SurfaceType.Smooth
		p.Material = Enum.Material.Asphalt
		p.Color = ROADC[r[i + 7]] or ROADC[1]
		p.Size = Vector3.new(w, 1.2 * S, len + w * 0.5)
		-- part centre sits 0.6 m below the road surface (thick slab, so it meets the ground)
		p.CFrame = CFrame.lookAt((a + b) / 2, b) * CFrame.new(0, -0.6 * S, 0)
		p.Name = "Road"
		p.Parent = roadsF
		n += 1
		if n % 1500 == 0 then task.wait() end
	end
end

-- ---- buildings: OSM footprint pieces (rectangles), estimated heights where OSM has none ----
local BC = {
	[0] = Color3.fromRGB(214, 200, 176), [1] = Color3.fromRGB(226, 214, 190), [2] = Color3.fromRGB(205, 192, 170),
	[3] = Color3.fromRGB(190, 186, 176), [4] = Color3.fromRGB(170, 166, 160), [5] = Color3.fromRGB(236, 230, 214),
	[6] = Color3.fromRGB(180, 196, 205), [7] = Color3.fromRGB(160, 150, 136),
}
for _, b in ipairs(chunks("Buildings")) do
	for i = 1, #b, 8 do
		local w, d, h = b[i + 2] * D, b[i + 3] * D, b[i + 5] * D + 1 * S
		local p = Instance.new("Part")
		p.Anchored = true
		p.CanTouch = false
		p.Material = Enum.Material.Concrete
		p.Color = BC[b[i + 7]] or BC[0]
		p.Size = Vector3.new(w, h, d)
		p.CFrame = CFrame.new(b[i] * D, b[i + 6] * D - 1 * S + h / 2, b[i + 1] * D) * CFrame.Angles(0, b[i + 4] / 1000, 0)
		p.Name = "Building"
		p.Parent = bldF
		n += 1
		if n % 1500 == 0 then task.wait() end
	end
end

-- ---- landmark name labels (visible within ~600 studs) ----
for _, L in ipairs(Meta.labels) do
	local p = Instance.new("Part")
	p.Anchored = true
	p.CanCollide = false
	p.CanQuery = false
	p.CanTouch = false
	p.Transparency = 1
	p.Size = Vector3.new(1, 1, 1)
	p.Position = Vector3.new(L.x * S, L.y * S + 18 * S, L.z * S)
	p.Name = "Label"
	local g = Instance.new("BillboardGui")
	g.Size = UDim2.fromOffset(260, 40)
	g.MaxDistance = 700
	g.AlwaysOnTop = false
	local t = Instance.new("TextLabel")
	t.Size = UDim2.fromScale(1, 1)
	t.BackgroundTransparency = 1
	t.TextScaled = true
	t.Font = Enum.Font.GothamBold
	t.TextColor3 = Color3.new(1, 1, 1)
	t.TextStrokeTransparency = 0.3
	t.Text = L.n
	t.Parent = g
	g.Parent = p
	p.Parent = map
end

-- spawn point at the web game's start (Baghdad Street, Al-Balad)
local sp = Instance.new("SpawnLocation")
sp.Anchored = true
sp.Size = Vector3.new(6, 1, 6)
sp.Transparency = 1
sp.CanCollide = false
sp.CanQuery = false
sp.Position = Vector3.new(0, Meta.startY * S + 6, 0)
sp.Parent = map

Workspace:SetAttribute("MapReady", true)
print(("Irbid Drive map built: %d roads, %d buildings, %d labels"):format(Meta.roadCount, Meta.buildingCount, #Meta.labels))
